-- Generated by Loom
-- Generator: hub
-- Hash function: SHA2
{{ config(materialized='incremental', incremental_strategy='append') }}
SELECT DISTINCT
    LOWER(SHA2(UPPER(TRIM(CAST(customer_id AS VARCHAR))), 256)) AS customer_hk,
    UPPER(TRIM(CAST(customer_id AS VARCHAR))) AS customer_id,
    'orders_system' AS __record_source,
    GETDATE() AS __loaded_at
FROM {{ ref('stg_customers') }}
WHERE customer_id IS NOT NULL
{% if is_incremental() %}
  AND LOWER(SHA2(UPPER(TRIM(CAST(customer_id AS VARCHAR))), 256)) NOT IN (
    SELECT target.customer_hk FROM {{ this }} AS target
  )
{% endif %}
